var o=[{title:`De onde vem o ruído`,text:`Os apoios repetidos dos pés, a corda de saltar, os burpees, as aterragens pesadas, o equipamento que rola e os halteres que caem transmitem som por um edifício. Os pisos finos podem fazer um pequeno impacto soar alto. Uma rotina que parece silenciosa num ginásio no rés do chão pode incomodar as pessoas que moram por baixo de um apartamento num andar de cima.`},{title:`Trocas mais silenciosas`,text:`Substitua os polichinelos por passos laterais, os agachamentos com salto por agachamentos controlados, a corrida no mesmo sítio por marcha e os burpees de alto impacto por versões com passo atrás. O shadow boxing, a caminhada rápida, a bicicleta estática e as subidas controladas a um degrau podem aumentar a respiração e a frequência cardíaca sem aterragens duras repetidas.`},{title:`Melhore a montagem`,text:`Treine num chão livre e antiderrapante. Um tapete de exercício pode abafar parte do som e proteger o chão, mas não consegue impedir que a vibração se propague pela estrutura. Pouse os pesos de forma deliberada e não empilhe equipamento solto. Verifique se uma plataforma de degrau ou um banco balança e faz barulho em cada repetição.`},{title:`Intensidade sem impacto`,text:`A dificuldade que o cardio parece ter depende do seu esforço, e saltar é apenas uma forma de o aumentar. Intervalos mais longos, descansos mais curtos que ainda permitam recuperar ou movimento contínuo de baixo impacto desenvolvem todos o condicionamento. No treino de força, os levantamentos lentos e controlados e as pausas podem dar muito trabalho e manter-se silenciosos, por isso não há necessidade de se apressar para que uma sessão pareça mais difícil.`},{title:`Usar o TrainUp`,text:`No Perfil, se pode saltar e quanto ruído é aceitável são duas definições separadas. Se limitar ambas, o plano deixa de fora os saltos, a corda de saltar e outros exercícios de pancada e continua a treinar em direção ao seu objetivo com outros mais silenciosos. Um tapete, por si só, não torna silencioso um exercício de saltos.`}];var s=[{label:`Recomendações do CDC sobre atividade física para adultos`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`},{label:`CDC: medir a intensidade da atividade e o teste da conversa`,url:`https://www.cdc.gov/physicalactivity/basics/measuring/index.html`},{label:`Biblioteca de exercícios da ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`}];var r={sections:o,sources:s};export{r as default,o as sections,s as sources};